import{_ as a,o as s,c as e,a2 as o}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"Prompt 结构通法","description":"","frontmatter":{},"headers":[],"relativePath":"prompts/structure.md","filePath":"prompts/structure.md","lastUpdated":1785729506000}'),n={name:"prompts/structure.md"};function d(p,t,r,l,i,c){return s(),e("div",null,[...t[0]||(t[0]=[o(`<h1 id="prompt-结构通法" tabindex="-1">Prompt 结构通法 <a class="header-anchor" href="#prompt-结构通法" aria-label="Permalink to &quot;Prompt 结构通法&quot;">​</a></h1><p>读完这一篇，你不需要背模板，可以自己写任何场景的 Prompt。</p><h2 id="五段式" tabindex="-1">五段式 <a class="header-anchor" href="#五段式" aria-label="Permalink to &quot;五段式&quot;">​</a></h2><p>一条视觉 Prompt 由五个部分组成，<strong>按重要性从前往后排</strong>。多数模型对靠前的词权重更高。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[主体] + [风格] + [镜头] + [光影] + [参数]</span></span></code></pre></div><table tabindex="0"><thead><tr><th>段</th><th>回答的问题</th><th>例子</th></tr></thead><tbody><tr><td><strong>主体</strong></td><td>画什么？谁在做什么？</td><td>一瓶琥珀色的威士忌放在深色木桌上，旁边有一块正在融化的冰</td></tr><tr><td><strong>风格</strong></td><td>什么调性？像什么？</td><td>高端酒类广告摄影，暗调，胶片质感</td></tr><tr><td><strong>镜头</strong></td><td>怎么拍？</td><td>微距，浅景深，f/1.8，平视</td></tr><tr><td><strong>光影</strong></td><td>光从哪来？什么质感？</td><td>侧逆光，一束硬光穿过瓶身，背景压暗</td></tr><tr><td><strong>参数</strong></td><td>技术规格</td><td>竖版 9:16，高细节</td></tr></tbody></table><p>完整拼起来：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>一瓶琥珀色威士忌放在深色木桌上，旁边一块正在融化的冰，</span></span>
<span class="line"><span>高端酒类广告摄影，暗调，胶片质感，</span></span>
<span class="line"><span>微距镜头，浅景深，f/1.8，平视机位，</span></span>
<span class="line"><span>侧逆光，一束硬光穿过瓶身在桌面投下琥珀色光斑，背景压暗，</span></span>
<span class="line"><span>竖版 9:16，高细节</span></span></code></pre></div><h2 id="每一段怎么写" tabindex="-1">每一段怎么写 <a class="header-anchor" href="#每一段怎么写" aria-label="Permalink to &quot;每一段怎么写&quot;">​</a></h2><h3 id="主体-具体-且只描述-能看见的东西" tabindex="-1">主体：具体，且只描述&quot;能看见的东西&quot; <a class="header-anchor" href="#主体-具体-且只描述-能看见的东西" aria-label="Permalink to &quot;主体：具体，且只描述&quot;能看见的东西&quot;&quot;">​</a></h3><p>这是最容易写错的一段。两个原则：</p><p><strong>一、写视觉，不写概念。</strong></p><table tabindex="0"><thead><tr><th>❌ 概念</th><th>✅ 视觉</th></tr></thead><tbody><tr><td>温馨的家庭氛围</td><td>三个人围坐在铺着格纹桌布的餐桌旁，桌上有热汤冒着白汽</td></tr><tr><td>高端大气</td><td>大理石台面，金属反光，大量留白</td></tr><tr><td>年轻活力</td><td>穿亮橙色卫衣的人跳起来，头发甩起</td></tr></tbody></table><p>模型不理解&quot;温馨&quot;，它理解&quot;热汤冒白汽&quot;。**每次你想写形容词的时候，问自己：这个形容词对应的画面是什么？**写那个画面。</p><p><strong>二、控制数量。</strong></p><p>一个画面里写超过三个主要元素，模型会开始丢东西或者把它们糊在一起。想要复杂场景，宁可拆成多张图后期合成。</p><h3 id="风格-给参照物比给形容词有效" tabindex="-1">风格：给参照物比给形容词有效 <a class="header-anchor" href="#风格-给参照物比给形容词有效" aria-label="Permalink to &quot;风格：给参照物比给形容词有效&quot;">​</a></h3><p>&quot;有质感&quot;没有信息量。有效的写法是给出可对标的<strong>类别</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>高端汽车广告摄影 / 北欧极简产品摄影 / 90 年代胶片人像 /</span></span>
<span class="line"><span>杂志内页编辑摄影 / 电商白底商品图 / 纪录片纪实风格</span></span></code></pre></div><p>这些词在训练数据里对应大量一致的视觉特征，模型能准确响应。</p><div class="warning custom-block"><p class="custom-block-title">关于模仿具体摄影师或品牌</p><p>用在世艺术家或摄影师的名字来指定风格，在多数商业场景下有法律和伦理风险，部分平台的使用条款也明确禁止。**商用项目请用风格类别描述（&quot;暗调静物摄影&quot;），不要用人名。**这不只是合规问题——描述风格特征本身也比蹭名字更可控。</p></div><h3 id="镜头-三个关键词就够" tabindex="-1">镜头：三个关键词就够 <a class="header-anchor" href="#镜头-三个关键词就够" aria-label="Permalink to &quot;镜头：三个关键词就够&quot;">​</a></h3><ul><li><strong>焦段</strong>：<code>微距 macro</code>（产品细节）/ <code>35mm</code>（自然视角）/ <code>85mm 人像</code>（背景虚化）/ <code>广角 wide angle</code>（空间感、有畸变）</li><li><strong>景深</strong>：<code>浅景深 shallow depth of field</code>（虚化背景，显贵）/ <code>全景深 deep focus</code>（都清楚，显平）</li><li><strong>机位</strong>：见 <a href="/method/storyboard">分镜设计</a> 的机位表</li></ul><p>产品广告最常用的组合：<strong>微距 + 浅景深 + 平视或微俯</strong>。</p><h3 id="光影-质感的主要来源" tabindex="-1">光影：质感的主要来源 <a class="header-anchor" href="#光影-质感的主要来源" aria-label="Permalink to &quot;光影：质感的主要来源&quot;">​</a></h3><p>**这一段最值钱。**同样的主体、同样的风格，光写得好和不写，出来的东西差一个档次。</p><p>不写光的后果：模型给你平光，画面像证件照。</p><p>最通用的三个写法：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>侧逆光，主体边缘有一圈亮边，背景压暗</span></span>
<span class="line"><span>柔和的窗户光从左侧打来，右侧有自然的暗部</span></span>
<span class="line"><span>黄金时刻的低角度阳光，暖色，长投影</span></span></code></pre></div><h3 id="参数-按平台需求填" tabindex="-1">参数：按平台需求填 <a class="header-anchor" href="#参数-按平台需求填" aria-label="Permalink to &quot;参数：按平台需求填&quot;">​</a></h3><ul><li><strong>比例</strong>：<code>9:16</code> 竖屏 / <code>1:1</code> 方图 / <code>16:9</code> 横屏 / <code>4:5</code> 社媒</li><li><strong>质量</strong>：<code>高细节 highly detailed</code> / <code>8K</code>（不同模型的响应差异很大）</li><li><strong>负向词</strong>：多数工具支持排除项，产品图常排除 <code>文字、水印、变形的手、多余的肢体</code></li></ul><div class="warning custom-block"><p class="custom-block-title">参数写法因工具而异</p><p>具体的参数语法（<code>--ar 9:16</code> 还是下拉菜单）、支持哪些参数、上限是多少，各家不同且更新频繁。**以官网为准。**这里给的是&quot;该控制哪些维度&quot;，不是&quot;该敲哪些字符&quot;。</p></div><h2 id="视频-prompt-的差异" tabindex="-1">视频 Prompt 的差异 <a class="header-anchor" href="#视频-prompt-的差异" aria-label="Permalink to &quot;视频 Prompt 的差异&quot;">​</a></h2><p>视频比图像多一个维度：<strong>时间</strong>。所以五段式要扩成六段：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[主体] + [动作] + [风格] + [镜头与运镜] + [光影] + [参数]</span></span></code></pre></div><p>多出来的<strong>动作</strong>段，有三条规则：</p><p><strong>一、一个镜头只写一个动作。</strong></p><blockquote><p>❌ 她拿起杯子，喝了一口，然后转身走向窗边，推开窗户 ✅ 她缓慢地拿起杯子送到嘴边</p></blockquote><p>写复合动作，模型会做出诡异的动作混合体。想要连续动作，拆成多个镜头。</p><p><strong>二、动作要慢。</strong></p><p>AI 视频在快速运动上表现很差——肢体会扭曲、物体会变形。**主动写 <code>缓慢地 slowly</code>、<code>轻微地 subtly</code>。**大幅动作是当前技术的软肋，绕过它。</p><p><strong>三、运镜也只给一个。</strong></p><p><code>缓慢推近</code>可以，<code>先推近再左移然后上摇</code>不行。</p><h2 id="一个实用技巧-把风格段固定下来" tabindex="-1">一个实用技巧：把风格段固定下来 <a class="header-anchor" href="#一个实用技巧-把风格段固定下来" aria-label="Permalink to &quot;一个实用技巧：把风格段固定下来&quot;">​</a></h2><p>做一个项目时，把<strong>风格 + 光影 + 参数</strong>三段写成一个固定的&quot;风格包&quot;，存下来：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>【本项目风格包】</span></span>
<span class="line"><span>高端食品广告摄影，暖色调，轻微胶片颗粒，</span></span>
<span class="line"><span>侧逆光，柔和的轮廓光，背景自然虚化压暗，</span></span>
<span class="line"><span>竖版 9:16，高细节，无文字</span></span></code></pre></div><p>之后每个镜头的 Prompt = 主体和动作（每次改）+ 风格包（原样粘贴）。</p><p>这是控制跨镜头一致性最简单有效的办法。风格包中途改一个词，整组素材的调性就会飘。</p><h2 id="调试思路-出图不对时改哪一段" tabindex="-1">调试思路：出图不对时改哪一段 <a class="header-anchor" href="#调试思路-出图不对时改哪一段" aria-label="Permalink to &quot;调试思路：出图不对时改哪一段&quot;">​</a></h2><table tabindex="0"><thead><tr><th>症状</th><th>大概率是哪一段的问题</th></tr></thead><tbody><tr><td>画面内容不对，缺东西</td><td>主体：元素太多，或用了概念词</td></tr><tr><td>内容对，但很廉价</td><td>光影：没写光，或写了顺光</td></tr><tr><td>很好看，但不是这个调性</td><td>风格：参照类别给错了</td></tr><tr><td>太平、没重点</td><td>镜头：没写景深，或景别不对</td></tr><tr><td>视频里动作扭曲</td><td>动作：写得太快、太复杂</td></tr></tbody></table><p>**一次只改一段。**同时改三段，出来的结果不知道是哪一处起了作用，等于没调试。</p><h2 id="接着看" tabindex="-1">接着看 <a class="header-anchor" href="#接着看" aria-label="Permalink to &quot;接着看&quot;">​</a></h2><ul><li><a href="/prompts/product-still">产品静物 / 电商主图</a></li><li><a href="/prompts/video-storyboard">短视频分镜脚本</a></li></ul>`,53)])])}const g=a(n,[["render",d]]);export{u as __pageData,g as default};
